using System;
namespace DomainConsole.Shared {
 public static class ExecutionDiagnosis {
  public static string Code(int code)=>code+" (0x"+unchecked((uint)code).ToString("X8")+")";
  public static string Recommend(int code){switch(unchecked((uint)code)){case 0x80244010:return "Повторите поиск с сохранением кэша. После пяти автоматических повторов проверьте метаданные и обслуживание WSUS; не сбрасывайте SoftwareDistribution снова.";case 0x80246002:case 0x8007000D:return "После завершения задания очистите только Download и повторите скачивание один раз. При повторении сравните клиентский пакет с источником WSUS и проверьте CBS, сеть и диск.";case 0x80240034:return "Проверьте сеть и содержимое WSUS; очистка Download допустима только после завершения операций.";case 0x80070570:return "Проверьте указанный путь и диск; повторяющаяся нечитаемость требует диагностики файловой системы, а не бесконечных сбросов.";case 0x80096010:return "Сохраните внутренний код; проверьте подпись и целостность пакета на клиенте и WSUS. Не отключайте проверку подписи.";case 0x80070643:return "Найдите внутренний код установщика в WindowsUpdate.log и журнале пакета. Не выбирайте лечение только по общему коду.";case 0x80070020:return "Проверьте занятый файл и владельца блокировки. Для status.json требуется исправление записи статуса агента; очистка Windows Update не поможет.";default:return Explain(code);}}
  public static string Explain(int code){switch(unchecked((uint)code)){case 0:return "Код HRESULT 0 означает отсутствие ошибки; итог операции определяется также её ResultCode.";
case 0x80244010:return "Достигнут лимит обменов запросами с WSUS за один поиск. Это число обменов, а не обновлений. Повторите поиск без очистки кэша; при устойчивом повторении проверьте каталог и обслуживание WSUS.";
case 0x80240009:return "Другая операция Windows Update конфликтует с текущей. Проверьте фоновые задания; не очищайте кэш во время установки.";
case 0x80240016:return "Установка сейчас недопустима: выполняется другая установка либо требуется перезагрузка.";
case 0x80070020:return "Файл занят другим процессом. Важно проверить путь: status.json относится к агенту DomainConsole, а не к кэшу Windows Update.";
case 0x8007000D:return "Недопустимые данные при обработке пакета. Проверьте CBS; повторно скачайте пакет после завершения операций. Код не доказывает повреждение всего хранилища.";
case 0x80096010:return "Не прошла проверка цифровой подписи объекта. Проверьте пакет и источник WSUS; не отключайте проверку подписи.";
case 0x80070643:return "Общая ошибка установщика. Ищите внутренний код и журнал конкретного пакета; сброс Defender по одному этому коду не обоснован.";
case 0x800705B4:return "Истекло время ожидания операции. Проверьте движение загрузки, активный установщик и его журнал до остановки или очистки.";
case 0x80244022:return "WSUS ответил HTTP 503: служба временно недоступна. Проверьте WsusPool и нагрузку сервера.";
case 0x8024401B:return "Прокси требует авторизацию (HTTP 407). Проверьте доступ учётной записи SYSTEM и настройки WinHTTP.";
case 0x80072EFD:return "Не удалось подключиться к источнику. Проверьте адрес, порт, VPN, прокси и фаервол.";
case 0x80070002:case 0x80070003:return "Файл или путь не найден. Сопоставьте путь и этап: временная ошибка может быть исправлена последующей попыткой.";
case 12002:case 0x80072EE2:return "Истекло время сетевого запроса. Проверьте источник восстановления/обновлений, доступ из SYSTEM, разрешение доступа в Kerio, прокси и политики. Конкретный сервер этим кодом не определяется.";case 0x80246002:return "Контрольная сумма скачанного обновления не совпала с ожидаемой. Файл отклонён Windows; установка этого обновления не выполнялась. Проверьте кэш клиента, содержимое WSUS и путь передачи.";case 0x80240034:return "Не удалось скачать обновление. Проверьте содержимое WSUS, сеть и кэш загрузок.";case 0x80070570:return "Файл или каталог повреждён и нечитаем. Возможны повреждение загрузки, хранилища компонентов или диска.";case 0xc0000005:return "Нарушение доступа к памяти процесса. По этому коду нельзя определить виновный компонент.";case 0x80240022:return "Сбой операции обновления. Общий код WUA не устанавливает причину; проверьте конкретное обновление и WindowsUpdate.log.";case 0x800F081F:return "Не найдены исходные файлы восстановления. Проверьте подходящий источник и индекс образа.";case 5:case 0x80070005:return "Отказано в доступе. Проверьте права и разрешения.";default:return "Команда завершилась с ненулевым кодом. Подробности смотрите в выводе и журналах; код зависит от запущенной программы.";}}
 }
}

